package net.civeira.phylax.features.access.usermfarecoverycode.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.usermfarecoverycode.domain.UserMfaRecoveryCode;
import net.civeira.phylax.features.access.usermfarecoverycode.domain.event.UserMfaRecoveryCodeEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserMfaRecoveryCodeEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserMfaRecoveryCodeEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserMfaRecoveryCode entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
